-- Phase 4 (database), part 3: the 77 Tribe Cards for goals that do not exist yet, loaded as drafts.
-- Nothing here creates a goal. A goal (and its three weekly ideas) is made only when a pastor or director signs its card off,
-- community by community. Looks up every community and goal family by slug; a missing one stops the migration.
do $seed$

declare v_n integer;
begin
  insert into public.tribe_card_templates (
    slug, community_id, family_id, title, sort,
    who_for, loving_god, loving_others, loving_life, week12_outcome, arc_1, arc_2, arc_3, guardrail, track_slugs,
    rhythm_slot, rhythm_mode, who_leads_well, demand_structure, demand_connection, demand_teaching, demand_doing, sensitive)
  select v.slug, c.id, f.id, v.title, v.sort,
         v.who_for, v.loving_god, v.loving_others, v.loving_life, v.week12_outcome, v.arc_1, v.arc_2, v.arc_3, v.guardrail, v.track_slugs,
         v.rhythm_slot, v.rhythm_mode, v.who_leads_well, v.ds, v.dc, v.dt, v.dd, v.sensitive
    from (values
('validate-my-idea-with-real-customers','business-entrepreneurship','enterprise','Validate my idea with real customers',3,'Anyone with a business idea who has not yet asked the people who would pay for it.','We bring our ideas to God before we pour our savings into them, and we listen for correction as much as for approval.','We role-play customer conversations, say what we heard honestly and never flatter an idea to protect a feeling.','By week 12 each of us has spoken with at least fifteen possible customers and made a clear go, change or stop decision with evidence.','Fifteen customer conversations and a written go, change or stop decision.','Write the problem your idea solves and who has it. List twenty people who fit and book five short conversations.','Hold ten more conversations. Ask what they do now, what it costs them and what they would pay. Do not pitch. Write down their exact words.','Sort what you heard into patterns. Decide to go, change or stop, and share the evidence and your decision with the tribe.','Leaders do not promise that an idea will succeed or fail. They help members gather evidence and decide for themselves.',array['rising','builders']::text[],'weeknight-evening','online','Has tested an idea before building it, and can hear ''no'' without taking it personally.',2,1,3,2,false),
('register-my-business-and-open-a-business-account','business-entrepreneurship','enterprise','Register my business and open a business account',4,'Anyone running a business informally who is ready to make it official.','We ask God for courage to do the dull, necessary steps and we honour the rules of the land.','We share what each office, form and bank asked for, go through the steps together and tell each other the real costs.','By week 12 each of us has the registration steps done or booked, a separate business account and a simple habit of keeping business money apart from personal money.','Registration done or booked, a separate business account, and business money kept apart.','List what your business needs to be official: name, registration, tax number and account. Put a date and a cost next to each item.','Complete or book the next two items. Share what you learned so the next person in the tribe saves time.','Open the business account and move one week of business money into it. Write a one-page rule for keeping the two kinds of money apart.','Leaders do not give legal, tax or investment advice. They point to a qualified professional.',array['rising','builders','stewards']::text[],'weeknight-evening','online','Has registered a business in Nigeria and can explain the steps in plain words.',3,1,2,2,false),
('win-my-first-ten-paying-customers','business-entrepreneurship','enterprise','Win my first ten paying customers',5,'Anyone with something to sell who has fewer than ten customers.','We bring our business to God each week, and we price, promise and pay with honesty.','We test each other''s offers, introduce each other to customers, and celebrate every sale together.','By week 12 each of us has ten paying customers, a simple sales record and a weekly selling habit.','Ten paying customers, or the target the member set in week 1.','List twenty people who might need what you sell and talk to five of them this week. Ask what they would pay for.','Make one clear offer with a price and sell it to ten people. Write down every yes, every no and the reason given.','Keep a simple sales record, repeat what worked and drop what did not. Ask your best customer for one introduction.','Leaders do not give legal or tax advice. They point to a professional.',array['rising','builders']::text[],'weeknight-evening','online','Has sold to real customers and remembers how hard the first ten were.',3,1,2,3,false),
('price-my-offer-and-stop-undercharging','business-entrepreneurship','enterprise','Price my offer and stop undercharging',6,'Owners who suspect they charge too little and are afraid to say a higher number.','We ask God to free us from fear of people and from the love of money, and to price with fairness.','We practise saying our prices aloud, ask each other hard questions and refuse to let anyone apologise for fair pay.','By week 12 each of us knows what each offer costs us to deliver, has a written price list and has quoted the new prices to at least three customers.','A written price list built on real costs, and new prices quoted to three customers.','Work out what one sale really costs you in time, materials and tax. Write your current price next to it and look at the gap.','Write a price list with a reason beside each price. Practise saying every price aloud to someone in the tribe until it sounds calm.','Quote the new prices to three customers and write down what each said. Keep the price unless you hear a reason to change it.','Leaders do not set another member''s price or give financial advice. They ask questions and let the member decide.',array['rising','builders','stewards']::text[],'weeknight-evening','online','Has raised prices and kept customers. Can talk about money without shame.',2,2,3,2,false),
('hire-and-manage-my-first-employee','business-entrepreneurship','enterprise','Hire and manage my first employee',7,'Owners who are about to hire, or who hired someone and are struggling to lead them.','We ask God to help us treat every worker as a person He made, and to pay and speak with fairness.','We share what worked and what failed when we hired, role-play hard conversations and keep each other honest about how we treat staff.','By week 12 each of us has a written role for the first hire, a clear way to pay and review them, and one weekly check-in kept.','A written role, a fair pay and review plan, and a weekly check-in kept for a month.','Write what the first hire must do in five lines, and what you will stop doing yourself. Ask one owner in the tribe to read it.','Draft the offer: pay, hours, duties and trial period. Role-play the interview and the first day with someone in the tribe.','Hold a short weekly check-in with your hire. Write what is working and what is not, and share one lesson with the tribe.','Leaders do not give employment law, payroll or tax advice. They send members to a qualified professional.',array['builders','stewards']::text[],'weeknight-evening','online','Has hired and led staff in a small business and can speak plainly about getting it wrong.',2,3,2,2,false),
('keep-clean-books-and-pay-my-taxes-on-time','business-entrepreneurship','enterprise','Keep clean books and pay my taxes on time',8,'Owners whose records live in their head or in a pile of receipts.','We believe honest accounts honour God and we ask Him to keep us from hiding anything.','We swap simple templates, remind each other of deadlines and encourage each other to ask a professional for help.','By week 12 each of us records every sale and cost weekly, knows what tax is due and when, and has booked help where we need it.','Weekly records kept for the season, tax dates written down, and any professional help booked.','Gather every receipt and bank record from the last month into one place. Choose a simple way to record sales and costs.','Record every sale and cost each week for a month. Find out which taxes and filings apply to you and write down the dates.','Book time with an accountant for anything you cannot settle yourself. Set a calendar reminder for every date you wrote.','Leaders do not give tax, audit or accounting advice. They share simple habits and point to a qualified accountant.',array['builders','stewards']::text[],'weeknight-evening','online','Keeps tidy books for a business and is patient with people who find numbers frightening.',3,1,3,2,false),
('raise-capital-or-a-grant','business-entrepreneurship','enterprise','Raise capital or a grant',9,'Owners with a clear plan who need outside money and do not know where to start.','We ask God to guard our hearts from greed and from desperation, and to show us what is enough.','We read each other''s plans, ask the questions a funder would ask and share honest leads without hoarding them.','By week 12 each of us has a written plan with real numbers, a list of suitable funders and at least two applications or conversations done.','A plan with real numbers, a list of suitable funders, and two applications or conversations done.','Write what you need the money for, how much and what it will change. Put the numbers in one page.','List ten possible funders, grants or investors and read what each one asks for. Choose three that truly fit you.','Complete two applications or conversations. Share what you were asked and what you would answer differently.','Leaders do not give investment or legal advice or promise that money will come. They help members prepare honestly.',array['builders','stewards']::text[],'weeknight-evening','online','Has applied for a grant or raised money, including being turned down, and stayed honest in the process.',3,1,3,2,false),
('lead-my-business-with-integrity-under-pressure','business-entrepreneurship','enterprise','Lead my business with integrity under pressure',10,'Owners who feel pressure to cut corners, pay late, bribe or bend the truth to survive.','We say plainly where we are tempted and ask God for courage to do right when it costs us.','We tell each other the truth, share how we handled hard offers and refuse to judge a member who is struggling.','By week 12 each of us has written our own lines we will not cross, told one trusted person, and handled one real pressure without compromising.','A written list of lines not to cross, shared with one person, and one pressure handled well.','Write three lines you will not cross in your business, whatever it costs. Say them aloud to one person in the tribe.','Tell the tribe about one current pressure. Ask what it would look like to handle it with honesty and write your next step.','Take that step. Report what happened, what it cost and what you learned, so the tribe can pray and learn with you.','Leaders do not give legal advice or judge what a member has done. Serious wrongdoing goes to the pastor.',array['builders','stewards','sages']::text[],'weeknight-evening','in_person','Has faced real pressure in business and chose the harder right. Listens without shock.',1,3,2,2,false),
('earn-a-promotion-or-a-raise-i-can-defend','professionals','career-calling','Earn a promotion or a raise I can defend',3,'Employees who have taken on more than their title or pay reflects, and want to ask well.','We ask God to keep us free of envy and bitterness, and to help us ask honestly and wait patiently.','We help each other list real results, rehearse the conversation and encourage each other to ask.','By week 12 each of us has a written list of results with numbers, has practised the request aloud and has made it to the right person.','A written list of results, a rehearsed request, and the conversation held.','Write down what you delivered in the last year, with numbers where you can. Note what your manager says they value most.','Draft what you will ask for and why, in five sentences. Rehearse it aloud with someone in the tribe until you can say it calmly.','Book the conversation and hold it. Report what was said, thank the tribe, and write your next step whatever the answer was.','Leaders do not promise a raise or give legal or HR advice. They help members prepare and leave the decision to the employer.',array['rising','builders','stewards']::text[],'weeknight-evening','online','Has asked for and received a raise or promotion with evidence, and can coach without pushing.',3,1,3,2,false),
('build-a-reputation-for-excellent-work','professionals','career-calling','Build a reputation for excellent work',4,'Professionals who want to be known as dependable, skilled and fair at work.','We treat our work as something we do for God, and we hold ourselves to the standard He would.','We give each other honest feedback, celebrate good work and refuse to spread rumours or take credit.','By week 12 each of us has asked three colleagues for feedback, chosen one habit that improves our work and kept it every week.','Feedback from three colleagues, and one improving work habit kept every week.','Describe in three lines how you want colleagues to describe your work. Ask three colleagues for one honest strength and one improvement.','Pick one habit that would lift your work, such as finishing early, checking twice or replying within a day. Do it every day this month.','Ask one person who relies on you what would make you more useful. Act on the answer and tell the tribe the result.','Leaders do not ask members to name or criticise colleagues. The tribe talks about its own habits only.',array['rising','builders','stewards']::text[],'weeknight-evening','online','Is known for dependable work and can say how they built that. Gives plain, kind feedback.',3,1,2,3,false),
('find-a-mentor-and-become-one','professionals','career-calling','Find a mentor, and become one',5,'Professionals who want a guide for their next stage and someone younger to pour into.','We thank God for the people who shaped us and ask Him to make us people who shape others well.','We introduce each other to wise people, practise good questions and take turns being the one who listens.','By week 12 each of us has asked one person to mentor us, met them at least twice and begun to encourage someone younger.','A mentor asked and met twice, and one younger person encouraged on a regular basis.','Write down what you want to learn and who is already doing it. Choose one person to ask and write your request in three sentences.','Ask. Meet your mentor, bring two questions and write one thing to try. Also find one younger person you can encourage.','Meet your mentor again and report what you tried. Meet your younger person and pass on one lesson from your own life.','Leaders do not pair members with mentors or promise that anyone will agree. Members ask for themselves.',array['rising','builders','stewards','sages']::text[],'weeknight-evening','online','Has been mentored and mentors someone now. Warm, patient and good at asking questions.',1,3,3,1,false),
('gain-a-skill-or-certification-in-my-field','professionals','career-calling','Gain a skill or certification in my field',6,'Professionals who know one skill or certificate would open their next step.','We study as an act of worship and ask God to give us diligence and humility.','We hold each other to study hours, quiz one another and share notes and good resources.','By week 12 each of us has chosen the skill or certificate, kept a weekly study block and finished a defined part of it.','The skill or certificate chosen, a weekly study block kept, and a defined part finished.','Name the skill or certificate your next step needs, what it costs and when you want to finish. Choose one way to begin this week.','Set a weekly study block and protect it. Study with one person from the tribe once a week and quiz each other.','Finish a clear part of the course or practise paper under timed conditions. Share what you learned and what you will repeat.','Leaders do not recommend paid courses or take payment from members. They share only free tips and what worked for them.',array['rising','builders','stewards']::text[],'weeknight-evening','online','Has earned a professional certificate while working and can share how they found the time.',3,1,3,2,false),
('manage-my-time-and-energy-at-work','professionals','career-calling','Manage my time and energy at work',7,'Professionals who are always busy, always behind and tired.','We make room for rest, prayer and Sabbath because we trust God with what we cannot finish.','We check on each other''s load, share what works and say no together instead of alone.','By week 12 each of us has a weekly plan we follow, one protected rest block and one habit that cuts wasted time.','A weekly plan followed, a protected rest block and one time-saving habit kept.','Track where your time and energy go for one week. Circle the biggest drain and the best use of your hours.','Plan each week on Sunday, with three priorities and one protected rest block. Share your plan with a partner in the tribe.','Stop or reduce one time-waster. Review the season with your partner and write the two habits you will keep.','Leaders do not give medical or mental health advice. If a member seems unwell, they encourage them to see a professional.',array['rising','builders','stewards']::text[],'weeknight-evening','online','Has learned to work well without overworking. Calm and organised, not preachy about it.',3,2,2,2,false),
('handle-workplace-conflict-with-grace','professionals','career-calling','Handle workplace conflict with grace',8,'Professionals in tension with a colleague, a manager or a team, who want to respond well.','We ask God to guard our words, soften our hearts and show us our part in every conflict.','We listen without taking sides, rehearse hard conversations and pray for the people we find difficult.','By week 12 each of us has had one honest conversation we were avoiding, owned our part and kept our tone calm.','One avoided conversation held, with our own part owned and the tone calm.','Describe the conflict in four sentences without blaming. Write what you want, what the other person might want and your own part.','Rehearse the conversation aloud with someone in the tribe. Hold it, starting with what you appreciate, then what you need.','Follow up with a kind message or a small act of respect. Share what changed and what you learned with the tribe.','Leaders do not give legal or HR advice, and the tribe never discusses a colleague''s private life. Cases of abuse or harassment go to the care ladder.',array['rising','builders','stewards']::text[],'weeknight-evening','online','Has handled a difficult workplace conflict well and can stay calm when others are upset. Does not take sides.',2,3,2,2,true),
('plan-the-next-five-years-of-my-career','professionals','career-calling','Plan the next five years of my career',9,'Professionals who drift from year to year and want a prayerful, practical plan.','We ask God to show us the work He has for us and we hold our plans loosely.','We ask each other honest questions, share what we see in one another and keep each other accountable to the plan.','By week 12 each of us has a one-page five-year plan, a plan for this year and one step taken from it.','A one-page five-year plan, a plan for this year and one step taken.','Write where you are now, what you enjoy and what you want more of. Ask two friends what strengths they see in you.','Draft a one-page plan for five years and a smaller plan for this year. Mark the skills, people and money you will need.','Take the first step on this year''s plan. Share the plan with the tribe and agree who will ask about it in three months.','Leaders do not predict anyone''s future or tell members which job to take. They help them think and decide.',array['rising','builders','stewards']::text[],'weeknight-evening','online','Has planned a career with intention and revised the plan when life changed. Asks good questions.',3,2,2,2,false),
('land-my-first-three-clients','consulting','enterprise','Land my first three clients',3,'New consultants and freelancers with skill but no regular clients.','We bring our work to God daily and ask Him for the right first clients, not just any clients.','We share leads, review each other''s messages and give honest feedback on how we describe our work.','By week 12 each of us has a clear one-sentence offer, has contacted at least thirty people and has three paying clients or the next best step.','Three paying clients, or a clear next step with dates.','Write one sentence that says who you help and with what. List thirty people who know someone who needs that.','Message ten people a week with a short, clear ask. Offer one free, small piece of help to build trust.','Turn your best conversation into a written offer with a price. Follow up on every open lead and report to the tribe.','Leaders do not give legal, tax or financial advice. They point to a qualified professional.',array['rising','builders']::text[],'weeknight-evening','online','Remembers the first three clients and how uncertain it felt. Practical and encouraging.',2,2,2,3,false),
('turn-one-off-projects-into-retainers','consulting','enterprise','Turn one-off projects into retainers',4,'Consultants who finish a project and start from nothing again.','We ask God for a long view and for the patience to serve clients well beyond the first sale.','We share how we propose ongoing work, role-play the conversation and cheer every renewal.','By week 12 each of us has designed an ongoing service, offered it to three past or present clients and agreed one monthly arrangement.','An ongoing service designed and offered to three clients, and one monthly arrangement agreed.','List your past clients and what they needed after the project ended. Write one ongoing service that meets that need.','Price the service per month with a clear scope. Practise the conversation with someone in the tribe.','Offer it to three clients and report back. Agree one arrangement and write down what you will deliver each month.','Leaders do not give legal, tax or financial advice. They point to a qualified professional.',array['builders','stewards']::text[],'weeknight-evening','online','Holds retainer clients and knows what keeps them. Good at structure and follow-through.',3,1,3,2,false),
('build-a-visible-expert-brand','consulting','enterprise','Build a visible expert brand',5,'Consultants who do good work that few people know about.','We ask God to keep our hearts humble as we make our work known and to help us speak truthfully.','We read each other''s posts and bios, share honest feedback and promote each other''s work.','By week 12 each of us has a clear profile, has published at least six useful pieces and has had one conversation that came from them.','A clear profile, six useful pieces published, and one conversation that came from them.','Write what you want to be known for, in one sentence. Update your profile so a stranger can see it in ten seconds.','Publish one useful piece a week for six weeks, such as a short post, a checklist or a case lesson. Ask the tribe for feedback first.','Reach out to three people who read your pieces. Note which pieces worked best and plan the next six.','Leaders do not guarantee results from posting and do not ask members to share the tribe''s private conversations online.',array['rising','builders','stewards']::text[],'weeknight-evening','online','Has built a name in their field through useful work and writing, and shares without boasting.',2,2,3,3,false),
('write-proposals-and-contracts-that-protect-me','consulting','enterprise','Write proposals and contracts that protect me',6,'Consultants who have been paid late, been asked for extra work or never had a written agreement.','We ask God to help us keep our word and to ask others to keep theirs, without bitterness.','We share templates, read each other''s proposals and help each other say no to unfair terms.','By week 12 each of us has a standard proposal, a written agreement with scope and payment terms, and has used it with a real client.','A standard proposal and a written agreement with scope and payment terms, used with a client.','Collect any agreement you have used. List what went wrong with clients before: late pay, extra work or unclear scope.','Draft a standard proposal and agreement covering scope, price, payment dates and changes. Have a lawyer or experienced person check it.','Use it with your next client. Share what they asked about and what you would change.','Leaders do not write or approve contracts and do not give legal advice. They share simple templates and point to a lawyer.',array['builders','stewards']::text[],'weeknight-evening','online','Has lost money to a vague agreement and now works with clear terms. Calm about hard conversations.',3,1,3,2,false),
('build-a-partner-network-or-small-team','consulting','enterprise','Build a partner network or small team',7,'Consultants who turn work away because they are a team of one.','We ask God to help us share work and credit generously, and to choose partners with character.','We introduce each other to trusted people, share referrals fairly and call each other to account if we fail a partner.','By week 12 each of us has met five possible partners, agreed terms with one and delivered or planned one shared piece of work.','Five possible partners met, terms agreed with one, and a shared piece of work delivered or planned.','List the kinds of work you turn away and the skills a partner would need. Write the names of ten people you trust or admire.','Meet five of them. Ask what they need, share what you need and agree how credit and money would be shared.','Agree terms with one partner in writing and plan one shared piece of work. Report how it went.','Leaders do not give legal, tax or financial advice. They point to a qualified professional.',array['builders','stewards']::text[],'weeknight-evening','online','Works with partners or a small team and knows what fair sharing looks like.',2,3,2,2,false),
('set-boundaries-so-clients-do-not-run-my-week','consulting','enterprise','Set boundaries so clients do not run my week',8,'Consultants who answer at all hours and say yes to everything.','We keep a rest day because we trust God to provide when we stop.','We remind each other of the lines we set, role-play saying no and celebrate each time we keep one.','By week 12 each of us has written working hours, a rule for urgent requests and one rest day we protect.','Written working hours, a rule for urgent requests and one protected rest day.','Write what a good week looks like and where clients break it. Choose your working hours and one rest day.','Tell your clients about your hours and how to reach you in an emergency. Practise saying the message aloud first.','Keep the hours for a month and note what clients said. Share what you will keep and adjust.','Leaders do not give mental health advice. If a member seems overwhelmed, they encourage them to speak to a professional.',array['builders','stewards']::text[],'weeknight-evening','online','Has set firm, kind boundaries with clients and kept their clients. Honest about how hard that was.',2,3,1,2,false),
('build-a-cv-and-linkedin-profile-that-gets-replies','in-between-jobs','career-calling','Build a CV and LinkedIn profile that gets replies',3,'Job seekers who send applications and hear nothing.','We ask God to help us describe our gifts honestly, without shrinking or boasting.','We read each other''s CVs with kindness and honesty, and we correct each other''s language and formatting.','By week 12 each of us has a one-page CV in a clear format, a complete profile, and has sent both to ten people or roles.','A clear one-page CV, a complete profile, and both sent to ten people or roles.','Write your achievements as results, such as what you improved, saved or built. Ask a trusted person to tell you your three strongest.','Redraft your CV to one page and match your profile to it. Have two people in the tribe read both and mark anything unclear.','Send the CV and profile to ten people or roles. Note which versions drew replies and improve the next.','Leaders do not write members'' CVs or invent achievements. Everything on a CV must be true.',array['rising','builders','stewards']::text[],'weeknight-evening','online','Has read many CVs or hired people, and can explain what makes one clear.',3,1,3,2,false),
('prepare-for-interviews-and-negotiate-an-offer','in-between-jobs','career-calling','Prepare for interviews and negotiate an offer',4,'Job seekers who freeze in interviews or take the first offer without asking.','We ask God for calm, honest words and a fair outcome.','We hold mock interviews for each other, give plain feedback and pray before the big days.','By week 12 each of us has practised ten common questions aloud, gone through at least two mock interviews and rehearsed a salary conversation.','Ten questions practised, two mock interviews done and a salary conversation rehearsed.','Write answers to the ten questions you most dread. Say them aloud to a partner in the tribe until they sound like you.','Hold two mock interviews in the tribe. Ask for one thing you did well and one you must change.','Practise how you will ask about pay and conditions. After any real interview, write what went well and share it.','Leaders do not promise outcomes or coach members to exaggerate. Honest answers only.',array['rising','builders','stewards']::text[],'weeknight-evening','online','Has hired people or interviewed well, and can give straight feedback with kindness.',2,2,3,3,false),
('earn-while-i-search','in-between-jobs','career-calling','Earn while I search',5,'People between jobs who need some income now without losing sight of their next role.','We ask God to provide, and we do honest work with thanks, whatever its size.','We share short-term work leads, encourage each other when pride gets in the way and celebrate every honest naira earned.','By week 12 each of us has found at least one source of honest income that fits our search and has kept a weekly record of what we earn.','One source of honest income found, and a weekly record of what is earned.','List the skills and contacts you have that someone would pay for this month. Choose one way to earn that fits your search.','Make five offers or applications for short-term work. Share leads you cannot use with the tribe.','Keep a simple record of what you earn each week. Decide how much time the work gets so your search continues.','Leaders do not give financial, legal or immigration advice. They point to a qualified professional.',array['rising','builders','stewards']::text[],'weeknight-evening','online','Has earned between jobs through small work or a side business without losing focus.',2,2,1,3,false),
('keep-my-confidence-and-routine-through-the-wait','in-between-jobs','career-calling','Keep my confidence and routine through the wait',6,'People between jobs whose days have lost shape and whose confidence has taken a knock.','We tell God honestly how it feels and remember that He sees our worth when no employer does.','We check on each other every few days, keep each other to a routine and never compare our timelines.','By week 12 each of us has a daily rhythm we keep, a weekly rest and a short note to ourselves about what we are proud of.','A daily rhythm kept, a weekly rest and a record of what we are proud of.','Write the shape of a good day: when you rise, work, move, rest and pray. Share it with a partner in the tribe.','Keep the daily rhythm for a month. Message your partner each morning with one line about your plan.','Write ten things you are proud of from the last ten years. Read three aloud to the tribe.','Leaders do not give mental health advice. If a member seems very low or unsafe, they use the care ladder the same day.',array['rising','builders','stewards']::text[],'weeknight-evening','online','Has waited through a long search and stayed steady. Warm, patient and a good listener.',2,3,1,2,true),
('grow-a-network-that-opens-doors','in-between-jobs','career-calling','Grow a network that opens doors',7,'Job seekers who know that most roles come through people and do not know how to start.','We ask God to help us build real friendships, not only contacts, and to give before we ask.','We introduce each other to people, practise short conversations and thank those who help us.','By week 12 each of us has had at least ten conversations with people in our field, followed up each one and offered help to someone in return.','Ten conversations with people in the field, each followed up, and help offered in return.','List thirty people who work where you want to work, or who know people who do. Choose ten to contact first.','Ask for a twenty-minute conversation with each of them. Ask what they wish they had known and who else you should speak to.','Thank each person within a day, report back with one useful thing and offer to help them in some way.','Leaders do not ask members to share contacts that belong to others without their consent. Introductions are made with permission.',array['rising','builders','stewards']::text[],'weeknight-evening','online','Has a wide, honest network and still builds it. Generous with introductions.',2,3,2,3,false),
('manage-money-well-on-a-reduced-income','in-between-jobs','career-calling','Manage money well on a reduced income',8,'People between jobs who need a clear plan for the money they have.','We trust God for our needs and ask Him to help us be honest and wise with what we have.','We share what we have learned about saving, encourage each other without shame and help where we can.','By week 12 each of us has a written budget for the reduced income, knows how many months it lasts and has made one cut or one saving.','A written budget, a clear count of how many months it lasts, and one cut or saving made.','Write what comes in and what goes out each month. Mark which items are needs and which can wait.','Draw up a budget for the reduced income and work out how many months it lasts. Make one cut or one saving.','Review the budget weekly with a partner in the tribe. Plan what you will do if the search takes longer.','Leaders do not give financial, legal or immigration advice. They point to a qualified professional. The tribe never asks members to disclose their debts.',array['rising','builders','stewards']::text[],'weeknight-evening','online','Has lived on less and kept dignity, and can talk about money without shame.',3,2,3,2,true),
('decide-between-another-job-and-working-for-myself','in-between-jobs','career-calling','Decide between another job and working for myself',9,'People between jobs who wonder whether to find a job or start something of their own.','We ask God for wisdom, we are willing to hear no, and we do not rush because we are afraid.','We ask each other hard, kind questions, share honest experience of both paths and respect each person''s choice.','By week 12 each of us has weighed both paths on paper, tested one with real people and made a written decision with a start date.','Both paths weighed on paper, one tested with real people, and a written decision with a start date.','Write what you would gain and lose on each path: money, time, risk, fit and family. Ask the tribe what they notice.','Test one path with real people. Apply for a role or talk to ten possible customers, and write what you hear.','Make a written decision with a date to begin and a plan for the first month. Share it with the tribe.','Leaders do not tell anyone which path to take. They help members think and decide for themselves.',array['builders','stewards']::text[],'weeknight-evening','online','Has faced this choice and made it. Even-handed about both paths and comfortable with uncertainty.',2,3,2,2,false),
('settle-in-a-new-country-and-find-my-footing','global-citizens','relationships','Settle in a new country and find my footing',3,'People who have recently moved abroad and are working out daily life, work and friendship.','We thank God for where we are, ask Him to show us why He has placed us here and trust Him through the strangeness.','We welcome the newest person first, share local knowledge and remember that every one of us was new once.','By week 12 each of us has a daily routine, three local friendships started and one way we are serving where we live.','A daily routine, three local friendships started and one way of serving locally.','Write what is hardest about the new place and what is already good. Set a simple daily routine and share it with the tribe.','Say hello to three neighbours or colleagues and arrange one coffee or meal. Try one local place or activity each week.','Find one way to give your time where you live. Tell the tribe what you have learned about the place and the people.','Leaders do not give immigration, legal or tax advice. They point to a qualified professional.',array['rising','builders','stewards']::text[],'sunday-evening','online','Has settled abroad and remembers the first months. Good at welcoming and at practical tips.',2,3,2,3,false),
('plan-a-return-home-well','global-citizens','relationships','Plan a return home well',4,'People living abroad who are thinking of going back, or have decided to.','We ask God to show us when and how to return, and to go back with open hands and a thankful heart.','We help each other count the cost, share honest stories of returning and pray for those at home who wait for us.','By week 12 each of us has a written return plan with dates, money, work and housing, and has spoken with family and our home church.','A written return plan with dates, money, work and housing, and conversations held with family and home church.','Write why you want to return, what you will miss and what you must settle before you go. Share it with the tribe.','List what a return needs: money, work, housing, papers and school for any children. Put a date and a person next to each item.','Speak with family and your home church about the plan. Write the first three things you will do on arrival.','Leaders do not give immigration, legal or tax advice. They point to a qualified professional.',array['builders','stewards']::text[],'sunday-afternoon','online','Has returned home after living abroad, or is planning to, and can speak about both the joy and the cost.',3,2,2,2,false),
('find-a-church-family-where-i-now-live','global-citizens','relationships','Find a church family where I now live',5,'People abroad or in a new city who miss the family of their home church.','We ask God to lead us to a place to belong and a place to serve, and we give thanks before we find it.','We share where we have visited, pray for each other''s search and encourage each other to go back more than once.','By week 12 each of us has visited at least three churches, chosen one to join and met a few people there by name.','Three churches visited, one chosen to join, and a few people there known by name.','List what matters to you in a church. Look up three churches near you and choose a Sunday to visit each.','Visit each one and write what you noticed. Introduce yourself to at least two people and ask about their lives.','Choose a church to join and tell them you are coming back. Offer to help with one small task.','Leaders do not criticise other churches or push anyone toward a church. Each member decides for themselves.',array['rising','builders','stewards','sages']::text[],'sunday-afternoon','online','Has found a church family far from home and can explain how long it took. Gentle and encouraging.',1,3,1,2,false),
('support-my-parents-from-a-distance','global-citizens','relationships','Support my parents from a distance',6,'Adult children abroad who carry worry and responsibility for ageing parents back home.','We bring our parents to God each week and ask Him for peace about what we cannot do from afar.','We listen to each other''s worries without rushing to fix them and share what has helped us care well from far away.','By week 12 each of us has a regular call schedule with our parents, a shared plan with our siblings and one practical support in place.','A regular call schedule, a plan agreed with siblings and one practical support in place.','Write what your parents most need and what you can do from where you are. Agree call times with them and keep them.','Talk with your siblings or a trusted relative about who does what. Put one practical support in place, such as a regular visitor or a monthly check.','Review the plan with your parents and your siblings. Share one honest struggle with the tribe and ask for prayer.','Leaders do not give medical, legal or financial advice. If a member is under strain, they use the care ladder.',array['builders','stewards','sages']::text[],'sunday-afternoon','online','Has cared for parents from abroad and knows the guilt and the cost. Steady and compassionate.',2,3,1,2,true),
('handle-papers-taxes-and-money-across-borders','global-citizens','relationships','Handle papers, taxes and money across borders',7,'People abroad who deal with visas, tax forms, bank accounts and sending money home.','We ask God for honesty in every form and every transfer, and for peace when the process is slow.','We share what we have learned about the process, encourage each other to ask professionals and remind each other of deadlines.','By week 12 each of us has a list of every paper and deadline that applies to us, a place to keep documents and an appointment booked where we need help.','A list of every paper and deadline, a safe place for documents and help booked where needed.','List every paper, permit, tax form and account you need in the countries involved. Write the deadline next to each.','Collect your documents in one safe place, with copies. Book help from a qualified person for anything you are unsure of.','Set reminders for every deadline and review the list monthly with a partner in the tribe.','Leaders do not give immigration, legal or tax advice. They point to a qualified professional.',array['builders','stewards']::text[],'sunday-afternoon','online','Has handled papers and money across countries carefully. Patient and organised, and clear about what they do not know.',3,1,3,2,false),
('raise-children-rooted-in-culture-and-faith-abroad','global-citizens','relationships','Raise children rooted in our culture and faith abroad',8,'Parents raising children abroad who want them to keep their language, culture and faith.','We ask God to give our children a faith of their own and to help us teach it with joy.','We swap ideas for stories, food, language and festivals, and we share the pressures our children face.','By week 12 each of us has a weekly family time for faith and culture, and one new practice our children have taken part in.','A weekly family time for faith and culture, and one new shared practice.','Write three things you want your children to carry from home. Choose one weekly time to share them as a family.','Add one new practice each month, such as a language night, a home dish or a Bible story told in your language.','Ask your children what they enjoyed and what they found hard. Share the answers and your next steps with the tribe.','Leaders do not criticise another family''s choices or give parenting rules. They share ideas and let each parent decide.',array['builders','stewards']::text[],'sunday-afternoon','online','Has raised children abroad with faith and culture intact, or is doing so now. Warm, practical and open to other views.',2,3,3,2,false),
('communicate-and-resolve-conflict-in-marriage','marriage-relationships','relationships','Communicate and resolve conflict in marriage',4,'Married couples who keep having the same argument and want better ways to speak and listen.','We ask God to soften our hearts, show us our own part and teach us to speak with patience.','We share what has helped us, never share what our spouse told us in confidence and refuse to take sides.','By week 12 each of us has practised a calm way of raising a problem, agreed a rule for arguing and used it at least three times.','A calm way of raising problems, a rule for arguing and its use at least three times.','Write the argument you repeat and how it usually ends. Each of you describes your own part, without the other''s.','Agree one rule for hard conversations, such as no phones, a pause when voices rise or one person speaks at a time. Use it three times.','Say thank you for one thing your spouse did in a hard moment. Share one thing you will keep doing with the tribe.','Leaders do not counsel couples or take sides. If there is fear, control or violence in a marriage, they use the care ladder the same day.',array['builders','stewards']::text[],'sunday-afternoon','in_person','Has worked at communication in their own marriage and can say how. Calm in tension and impartial.',2,3,2,1,true),
('manage-money-together-as-a-couple','marriage-relationships','relationships','Manage money together as a couple',5,'Married or engaged couples who disagree about money, or never talk about it.','We thank God for what we have, ask for wisdom and generosity and agree to give before we spend.','We share what has worked for us, keep each couple''s figures private and encourage openness without pressure.','By week 12 each couple has talked openly about income, debts and giving, written a shared budget and held a monthly money meeting three times.','Income, debts and giving discussed openly, a shared budget written and three monthly money meetings held.','Each of you writes what money means to you and what you fear. Share it with each other and do not argue about it.','Write one shared budget for the month with giving and saving in it. Agree who pays what and who tracks it.','Hold a short money meeting each month. Share with the tribe one habit you will keep, without sharing numbers.','Leaders do not give financial, investment or debt advice, and never ask couples to disclose figures to the tribe.',array['builders','stewards']::text[],'sunday-afternoon','in_person','Manages money openly with a spouse and has recovered from money disagreements. Practical and non-judging.',3,2,3,1,false),
('rebuild-trust-and-closeness-after-a-hard-season','marriage-relationships','relationships','Rebuild trust and closeness after a hard season',6,'Couples recovering from a season of distance, stress, loss or broken trust, who both want to move toward each other.','We ask God for forgiveness and healing, and for the patience to rebuild slowly.','We keep everything shared in the tribe in the tribe, encourage small steps and never press for details.','By week 12 each couple has a weekly time together, a way of saying sorry and forgiving, and one small act of closeness each day.','A weekly time together, a way to say sorry and forgive, and a daily act of closeness.','Agree one weekly time together with no phones. Start with a walk, a meal or a prayer. Do not use it to solve anything.','Each write a short note saying what you miss and what you hope for. Read them to each other and say thank you.','Choose one small daily act of closeness and keep it every day. Tell the tribe what has changed and what is still hard.','Leaders do not counsel couples. Affairs, abuse, addiction or any risk of harm are never handled in the tribe and go to the pastor or the care ladder the same day.',array['builders','stewards']::text[],'sunday-afternoon','in_person','Has seen a marriage through a hard season, or journeyed with others. Gentle, discreet and clear about their limits.',1,3,1,2,true),
('build-healthy-relationships-with-in-laws-family','marriage-relationships','relationships','Build healthy relationships with in-laws and family',7,'Married people who find family expectations and in-law relationships hard to handle.','We ask God to help us honour our families while putting our marriages first.','We listen without gossip, share what has worked and never speak badly of anyone''s relatives.','By week 12 each of us has agreed with our spouse on our family boundaries, held one honest and kind conversation with a relative and shown honour in one practical way.','Family boundaries agreed with a spouse, one kind conversation held and honour shown in one practical way.','Write where family expectations strain your marriage. Talk with your spouse about what you need to agree before you speak to anyone.','Agree two or three clear, kind boundaries and how you will say them. Rehearse with a partner in the tribe.','Have one conversation with a relative and do one practical act of honour for them. Share what happened and what you learned.','Leaders do not take sides in family disputes or counsel couples. If there is abuse or fear, they use the care ladder the same day.',array['rising','builders','stewards']::text[],'sunday-afternoon','in_person','Has navigated in-law and extended family relationships with patience, and can speak kindly of all sides.',2,3,2,2,false),
('date-with-purpose-and-clear-standards','marriage-relationships','relationships','Date with purpose and clear standards',8,'Singles who want to date intentionally, with faith and clear standards.','We ask God to guide who we meet and how we treat them, and to keep us pure in heart and conduct.','We ask each other honest questions, pray for each other''s relationships and speak up gently when we see danger.','By week 12 each of us has written our standards and non-negotiables, shared them with a mentor and set boundaries we have kept.','Written standards and non-negotiables shared with a mentor, and boundaries kept.','Write what you are looking for in a partner and what you bring. Separate what is essential from what is only preferred.','Share your list with a mentor or a trusted friend and ask what they notice. Set three boundaries for how you will date.','Review your boundaries with the tribe at the end of each month. Write what you will do when someone crosses one.','Leaders do not match people or advise on a particular person. If a member describes harm or pressure, they use the care ladder the same day.',array['rising','builders']::text[],'sunday-evening','online','Married or single with a godly track record, and able to speak plainly about dating without shaming anyone.',2,3,3,1,false),
('wait-well-stay-faithful-and-whole-while-single','marriage-relationships','relationships','Wait well: stay faithful and whole while single',9,'Single adults who long to marry, or who are single for a season, and want to live fully now.','We trust God with our timing and ask Him to fill what is empty, and we give thanks for today.','We include everyone, avoid pressuring each other about marriage and celebrate each other''s progress in other parts of life.','By week 12 each of us has a weekly habit that builds our life now, two friendships we invest in and one act of service.','A weekly habit that builds life now, two friendships invested in and one act of service.','Write what you are waiting for and what you can do while you wait. Choose one weekly habit that builds your life now.','Invest in two friendships with a regular meeting or call. Invite someone new into your week.','Serve someone else each week for a month. Share what you have learned about waiting.','Leaders do not match people or promise a spouse. If a member is very low or lonely, they use the care ladder.',array['rising','builders','stewards']::text[],'sunday-evening','online','Has lived single with joy, or waited well before marriage. Honest about loneliness and free of pity.',1,3,1,3,false),
('build-a-blended-family','marriage-relationships','relationships','Build a blended family',10,'Parents and step-parents bringing two families together, who want peace in the home.','We ask God for patience and for love that grows slowly, and for grace to forgive and to be forgiven.','We share honest stories without judging, keep every family''s details private and never compare children.','By week 12 each of us has a weekly time for the whole household, a clear and fair house rule agreed with our spouse and one one-to-one time with each child.','A weekly household time, a fair house rule agreed with a spouse and one-to-one time with each child.','Write what each person in the home has lost and what each hopes for. Share it with your spouse.','Agree one house rule with your spouse and explain it to the children together. Start a weekly time for the whole household.','Spend regular one-to-one time with each child, doing something they enjoy. Share one lesson with the tribe.','Leaders do not counsel families or take sides. If there is abuse, fear or risk to a child, they use the care ladder the same day.',array['builders','stewards']::text[],'sunday-afternoon','in_person','Lives in or has helped a blended family. Patient, impartial and discreet.',2,3,2,2,true),
('raise-young-children-in-faith','parents-family','faith-home','Raise young children in faith',3,'Parents and carers of children under twelve who want to pass on faith in simple, daily ways.','We tell our children about God in ordinary moments, and we ask Him to give them a faith of their own.','We swap stories, songs, games and prayers that work with young children and forgive each other''s tired days.','By week 12 each of us has a bedtime or mealtime prayer most days, has told our children one Bible story a week and has taught one verse.','A bedtime or mealtime prayer most days, a Bible story each week and one verse learned.','Choose one daily moment for a short prayer with your child, such as bedtime, breakfast or the school run. Keep it to one minute.','Tell your child one Bible story a week in your own words. Let them ask questions and act it out or draw it.','Learn one short verse together and say it each day. Share with the tribe what your child said or asked.','Leaders do not give parenting rules or counsel families. If a child may be at risk, they use the care ladder the same day.',array['rising','builders','stewards','sages']::text[],'sunday-evening','online','Has young children now or recently and makes faith easy and fun. Patient with tired parents.',2,2,3,3,false),
('discipline-with-love-and-consistency','parents-family','faith-home','Discipline with love and consistency',4,'Parents and carers who swing between shouting and giving in, and want a calm, firm and loving approach.','We ask God to give us the gentleness and strength we do not have, and to forgive us where we have been harsh.','We share honestly without shame, never compare children and encourage each other to say sorry to our children when we are wrong.','By week 12 each of us has agreed two or three clear family rules, followed through on them calmly and apologised once when we got it wrong.','Two or three clear family rules, calm follow-through, and an apology made when needed.','Write the one or two situations that make you lose your temper. Note what happens just before and what you could do instead.','Agree two or three clear family rules and what happens if they are broken. Explain them calmly to your children.','Follow through calmly for a month. When you get it wrong, say sorry to your child and tell the tribe how it felt.','Leaders never approve of hitting or humiliating a child and do not give parenting rules. If a child may be at risk, they use the care ladder the same day.',array['builders','stewards']::text[],'weeknight-evening','online','Has learned to discipline calmly and kindly, and can admit when they failed. Never harsh or boastful.',3,2,2,2,true),
('teach-my-children-money-and-responsibility','parents-family','faith-home','Teach my children money and responsibility',5,'Parents and carers who want their children to learn to earn, give, save and take responsibility.','We teach our children that everything belongs to God, and we give and save in front of them.','We share what has worked, what has failed and the chores, projects and games that taught our children something.','By week 12 each of us has given our children one regular job, a simple way to earn, give and save, and talked about money with them each week.','A regular job for each child, a way to earn, give and save, and a weekly talk about money.','Choose one regular job for each child that fits their age. Explain why the family shares the work.','Set up three jars or accounts: give, save and spend. Help your child decide how to divide what they receive.','Talk about money once a week at a normal moment. Share one thing your child said that surprised you.','Leaders do not give financial advice or discuss another family''s income. They share simple ideas for children only.',array['builders','stewards']::text[],'weeknight-evening','online','Has taught their own children about money and responsibility, with honest stories of what failed.',3,1,3,2,false),
('balance-work-and-family-without-losing-either','parents-family','faith-home','Balance work and family without losing either',6,'Working parents who feel stretched between the office and the home.','We trust God with what we cannot do, keep a day of rest and give Him our worry about both.','We say no to extra pressure together, share how we cover for each other and refuse to compare our time with anyone''s.','By week 12 each of us has a weekly family time we protect, one boundary at work we keep and a plan for the hardest day of the week.','A protected weekly family time, one work boundary kept and a plan for the hardest day.','Write what a good week looks like at home and at work. Mark the hour where each one costs the other most.','Protect one block of family time in your calendar and tell your family and your employer or clients. Keep it for four weeks.','Set one boundary at work and one at home. Share how each went with your tribe.','Leaders do not give parenting rules or counsel families. If a child may be at risk, they use the care ladder the same day.',array['builders','stewards']::text[],'weeknight-evening','online','Works and parents, and has learned to say no. Honest about the cost of both.',3,2,1,3,false),
('care-for-ageing-parents-well','parents-family','faith-home','Care for ageing parents well',7,'Adult children caring for, or about to care for, an ageing parent.','We honour our parents as God asks, and we ask Him for strength and for rest on the hard days.','We listen to the weight each of us carries, share practical help and never judge how another family cares.','By week 12 each of us has a care plan agreed with our family, one regular rest for ourselves and one safe person to speak to each week.','A care plan agreed with family, regular rest and a safe person to speak to each week.','Write what your parent needs and who can help. Call a family meeting or a trusted relative to share the load.','Agree who does what and how often, in writing. Book one regular rest for yourself, even a short one.','Review the plan with your family. Share with the tribe what is working, and what you still need.','Leaders do not give medical, legal or financial advice. If a parent or carer is at risk, they use the care ladder the same day.',array['builders','stewards','sages']::text[],'sunday-evening','online','Has cared for an ageing parent and knows the cost. Patient, compassionate and practical.',2,3,1,3,true),
('parent-well-as-a-single-parent','parents-family','faith-home','Parent well as a single parent',8,'Single parents, whether through loss, separation or choice, who want company, practical help and hope.','We trust God as the Father of our children and ask Him to fill the gaps that we cannot.','We help with the practical things, listen without judging how we came to this place and celebrate small wins.','By week 12 each of us has a weekly rhythm that works for our household, one reliable helper and one time of rest.','A weekly household rhythm that works, a reliable helper and a time of rest.','Write the week as it is, and mark the three hardest hours. Ask the tribe for one practical help for one of them.','Build a simple weekly rhythm for meals, school, bedtime and church, and share it. Name one reliable helper.','Book one regular rest for yourself. Offer one thing you can do for another parent in the tribe.','Leaders do not give legal, financial or counselling advice. If a child or parent is at risk, they use the care ladder the same day.',array['rising','builders','stewards']::text[],'weeknight-evening','online','Has raised children alone or supported single parents well. Respectful, practical and free of pity.',2,3,1,3,true),
('welcome-a-new-baby-and-the-first-year','parents-family','faith-home','Welcome a new baby and the first year',9,'Expecting parents and parents of a baby under one who want support, sleep and a good start.','We thank God for the gift of this child and ask Him to teach us to love without being perfect.','We bring meals, share what helped, cover for each other and never compare babies or parents.','By week 12 each of us has a simple plan for the early weeks, one person to call at night and a rest rhythm for the two of us.','A plan for the early weeks, a person to call at night and a rest rhythm.','Write what the early weeks will need: rest, meals, help and who to call. Share it with someone in the tribe.','Set up a simple routine for sleep, feeding and rest between you. Say yes to help when it is offered.','Share one thing that has been harder than expected and one thing that has been better. Pray for another family in the tribe.','Leaders do not give medical advice. If a parent seems very low or a baby seems unwell, they encourage urgent medical help and use the care ladder.',array['rising','builders']::text[],'sunday-evening','in_person','Has a young baby now or recently, and is gentle about the tiredness and the joy. Practical and kind.',2,3,2,2,false),
('support-my-children-s-education','parents-family','faith-home','Support my children''s education',10,'Parents and carers who want to help their children learn, from nursery to university.','We ask God to show us each child''s gifts and to help us support them without pressure or comparison.','We share good schools, tutors, books and routines, encourage each other when school is hard and refuse to boast about grades.','By week 12 each of us has met our child''s teacher, set a daily homework or reading time and asked our child what they love learning.','A meeting with the teacher, a daily homework or reading time, and a talk about what our child loves.','Ask your child what they enjoy and what they find hard at school. Listen for ten minutes and do not fix anything yet.','Meet your child''s teacher or school and ask how you can help. Set a daily homework or reading time that fits your household.','Review with your child what is working. Share one idea from the tribe that you will try next term.','Leaders do not recommend paid schools or tutors for money and do not compare children. They share ideas freely.',array['builders','stewards','sages']::text[],'weeknight-evening','online','Has supported children''s education through ups and downs. Encouraging and free of competition.',3,2,3,2,false),
('lose-weight-in-a-healthy-lasting-way','health-fitness-sports','health','Lose weight in a healthy, lasting way',3,'Adults who want to lose weight slowly, with a doctor''s guidance and no crash diets.','We thank God for our bodies as they are today and ask Him for self-control that comes with peace, not punishment.','We never shame, weigh in public or compare, and we encourage each other when we slip.','By week 12 each of us has seen a doctor if needed, built two eating habits and one movement habit we keep, and measured progress in ways that are not only the scale.','Two eating habits and one movement habit kept, with progress measured in more than the scale.','Write why you want to change and what you want your body to do for you. Book a visit with a doctor if you have any health concern.','Choose two eating habits and one movement habit to keep, such as drinking water, eating slowly or a daily walk. Share them with a partner.','Review what you have kept and how you feel, not only the scale. Pick the habits you will carry into the next season.','Leaders do not give diet plans, weight targets or medical advice, and never weigh members. If someone shows signs of an eating disorder, they use the care ladder the same day.',array['rising','builders','stewards']::text[],'saturday-morning','in_person','Has changed their own habits slowly and kindly, and speaks with compassion about food and weight. Never a fixer.',3,3,1,2,true),
('eat-well-on-a-real-budget','health-fitness-sports','health','Eat well on a real budget',4,'Anyone who wants to eat better but thinks it costs too much.','We give thanks for our food and ask God to help us feed ourselves and our families wisely.','We share recipes, market tips and swap ingredients and never shame what anyone can afford.','By week 12 each of us has a weekly meal plan on a set budget, cooks at home most days and has swapped at least three recipes.','A weekly meal plan on a set budget, most meals cooked at home and three recipes swapped.','Write what you spend on food in a week and what you eat most. Choose three cheap meals you can cook well.','Plan a week of meals and shop to a set budget. Share your best recipe and learn one from someone else.','Keep the plan for four weeks and cook most meals at home. Tell the tribe what saved you the most.','Leaders do not give medical diets or nutrition advice for a condition. They share ordinary cooking and shopping tips only.',array['rising','builders','stewards','sages']::text[],'saturday-morning','in_person','Cooks well on a modest budget and enjoys sharing. Generous and practical.',3,2,3,2,false),
('train-for-a-5k-10k-or-half-marathon','health-fitness-sports','health','Train for a 5K, 10K or half marathon',5,'Beginners and returning runners who want to complete a distance, with company.','We run, walk and rest as an act of thanks, and we ask God for patience and perseverance.','We run together, pace each other, wait for the slowest and celebrate every finish.','By week 12 each of us has trained three times a week, followed a simple plan and taken part in a race or a timed run for our chosen distance.','A simple plan followed, training three times a week and the chosen distance completed.','Choose your distance and race or test date. Do your first run or walk this week, however short, and write how it felt.','Follow a simple plan with three sessions a week and one rest day. Train with a partner and increase slowly.','Do a full practice of your distance. Run the race or timed event together and celebrate.','Leaders do not give medical advice, diets or exercise for a condition. Members see a doctor first where there is any doubt. Anyone with a heart or joint condition sees a doctor before starting.',array['rising','builders','stewards']::text[],'saturday-morning','in_person','Runs regularly and has finished a race. Encouraging to beginners and honest about injury and rest.',3,2,1,3,false),
('reset-my-sleep-stress-and-rest','health-fitness-sports','health','Reset my sleep, stress and rest',6,'Anyone who is tired and wired, sleeps badly or never switches off.','We rest because God rested, and we hand Him our worries before we sleep.','We keep each other to bedtimes, share what quiets our minds and remind each other that rest is not laziness.','By week 12 each of us has a fixed wake time, a wind-down routine we keep most nights and one regular day of rest.','A fixed wake time, a wind-down routine kept most nights and a regular day of rest.','Write your sleep, work and worry pattern for a week. Choose a wake time you can keep seven days a week.','Start a short wind-down routine, such as screens off, a prayer and a warm drink. Keep it most nights and share it with a partner.','Choose one regular day of rest and protect it. Tell the tribe what changed in your mood and energy.','Leaders do not give medical or mental health advice, and do not suggest sleep aids or medication. If a member''s sleep or mood is very poor, they encourage a doctor''s visit and use the care ladder.',array['rising','builders','stewards','sages']::text[],'sunday-evening','online','Has recovered a healthy rhythm of rest after a tiring season. Calm and steady, without lecturing.',3,2,2,1,true),
('recover-after-illness-or-injury','health-fitness-sports','health','Recover after illness or injury',7,'Anyone getting back to health after an illness, surgery or injury who needs patience and company.','We trust God with our healing and with the time it takes, and we thank Him for each small gain.','We visit, call and bring food, keep each other''s health details private and never compare recoveries.','By week 12 each of us has followed our medical team''s plan, built a small daily routine of recovery and had company each week.','The medical team''s plan followed, a daily recovery routine and weekly company.','Write what your doctor or therapist asked you to do and where you struggle to keep it. Ask the tribe to check in on one part.','Build a small daily routine of recovery, with rest, movement as allowed and one thing that lifts your mood. Share it each week.','Mark each small gain. Decide what you will keep doing after the season, and who will keep checking in.','Leaders do not give medical advice or tell anyone to stop or change treatment. They encourage members to follow their doctor''s plan.',array['builders','stewards','sages']::text[],'weeknight-evening','online','Has recovered from illness or injury or has cared for someone who did. Patient, gentle and good at simply being there.',1,3,1,2,true),
('play-a-team-sport-every-week','health-fitness-sports','health','Play a team sport every week',8,'Anyone who wants regular exercise through a team game and the friendship that comes with it.','We play as an act of joy and thanks, and we practise fairness and self-control on the pitch.','We include everyone, celebrate effort over talent and give each other grace when we lose.','By week 12 each of us has played at least ten times, helped organise the games and invited one new person.','At least ten games played, the games shared out among the group and one new person invited.','Choose a sport and a regular place and time. Invite at least six people to the first game.','Play every week and share the organising, such as booking the pitch, bringing the ball and bringing water. Welcome new players.','Invite someone who has never played with you. Share what the games have done for your body and your friendships.','Leaders do not give medical advice, diets or exercise for a condition. Members see a doctor first where there is any doubt. Anyone returning from injury checks with a doctor first.',array['rising','builders','stewards']::text[],'saturday-morning','in_person','Plays a team sport regularly and organises games fairly. Warm, inclusive and never a bully on the pitch.',2,3,1,3,false),
('build-healthy-habits-as-a-family','health-fitness-sports','health','Build healthy habits as a family',9,'Families who want to eat, move and rest better together.','We care for our bodies as a family because we belong to God, and we thank Him for each other.','We share ideas, join each other for family walks and games and never shame a child about their body.','By week 12 each family has a weekly active outing, three family meals a week and one agreed habit each member keeps.','A weekly active family outing, three family meals a week and one agreed habit each.','Ask each person in the family what healthy habit they would try. Choose one family habit everyone agrees on.','Plan a weekly active outing, such as a walk, a game or a bike ride. Cook and eat together three times a week.','Give each person one habit of their own. Share what worked and what the children said with the tribe.','Leaders do not give medical advice, diets or exercise for a condition. Members see a doctor first where there is any doubt. The tribe never comments on a child''s weight.',array['builders','stewards']::text[],'sunday-afternoon','in_person','Has built healthy habits with their own family, with humour and patience. Never a nag.',3,3,2,2,false),
('pass-a-professional-or-entrance-exam','education','learning','Pass a professional or entrance exam',3,'Anyone preparing for a professional, licensing or entrance exam, and who needs a plan and company.','We prepare with diligence and then trust God with the result, and we ask Him to keep our minds calm.','We set a study rhythm together, quiz one another and pray for each other on the days that matter.','By week 12 each of us has covered the syllabus on a plan, done at least three timed papers and booked the exam or the date.','The syllabus covered on a plan, three timed papers done and the exam date booked.','Get the full syllabus and the exam date. Divide the syllabus into twelve weeks and mark the weak topics.','Study to the plan each week and meet a partner to quiz each other on the hardest topics. Do one timed paper a fortnight.','Do timed papers under exam conditions and learn from each mistake. Plan the final week with rest and prayer.','Leaders do not share or look for leaked questions and never help anyone cheat. They study honestly.',array['rising','builders']::text[],'weeknight-evening','online','Has passed a professional or entrance exam and can explain how they prepared. Calm and organised.',3,1,3,2,false),
('finish-my-dissertation-or-project-on-time','education','learning','Finish my dissertation or project on time',4,'Students and researchers with a dissertation, thesis or long project that is stuck or slipping.','We bring our work to God, ask Him for clear thinking and for strength to finish what we began.','We set deadlines for each other, read each other''s drafts and celebrate every chapter.','By week 12 each of us has a chapter plan with dates, writes at fixed times each week and has handed a draft to a reader.','A chapter plan with dates, fixed writing times and a draft handed to a reader.','Write what is left to do and when it is due, chapter by chapter. Choose fixed writing times each week and tell the tribe.','Write at your fixed times and report your word count or pages each week. Send a draft chapter to a reader and ask for honest comments.','Edit one chapter at a time and finish the draft. Plan the final week before the deadline with the tribe.','Leaders do not write, edit or rewrite members'' work and never help anyone plagiarise. They help members plan and keep going.',array['rising','builders']::text[],'weeknight-evening','online','Has finished a long piece of academic work, and remembers the middle slump. Encouraging and firm about deadlines.',3,1,2,3,false),
('build-study-habits-that-last','education','learning','Build study habits that last',5,'Students who study in bursts, cram at the last minute and want a routine they can keep.','We treat our minds as a gift and ask God to give us focus and a love for learning.','We study together, keep each other accountable and share the methods that work.','By week 12 each of us has a daily study time, a place and method that work for us and a weekly review we keep.','A daily study time, a place and method that work, and a weekly review kept.','Track when and where you study well for one week. Choose a daily study time and a place that has few distractions.','Try one new method, such as testing yourself or teaching a friend, for a month. Share what you notice with a study partner.','Do a short weekly review of what you learned and what you will do next. Keep the habits you want for next term.','Leaders do not do members'' work or give medical advice. If a student seems unwell or overwhelmed, they encourage them to speak to a professional.',array['rising']::text[],'weeknight-evening','online','Studies steadily and can explain their own habits. Warm and free of pressure.',3,1,3,2,false),
('win-a-scholarship-or-a-place-abroad','education','learning','Win a scholarship or a place abroad',6,'Students and graduates applying for a scholarship, a fellowship or a place at a school or university abroad.','We ask God to open the right door, and we apply with honesty, humility and thankfulness.','We read each other''s essays, practise interviews and share leads without hoarding them.','By week 12 each of us has a shortlist of programmes, a draft personal statement read by two people and at least two complete applications sent.','A shortlist of programmes, a personal statement read by two people and two applications sent.','List five programmes that fit you and what each one asks for. Put every deadline in your calendar.','Write your personal statement, true to your story, and give it to two readers. Gather the documents and referees each programme needs.','Send at least two complete applications before their deadlines. Plan how you will respond to a yes or a no.','Leaders do not pay for or arrange admission or visas, and do not give immigration advice. They share only honest help.',array['rising','builders']::text[],'weeknight-evening','online','Has won a scholarship or studied abroad, or helped others do so. Honest about rejections.',3,1,3,2,false),
('lead-a-classroom-with-calm-and-confidence','education','learning','Lead a classroom with calm and confidence',7,'Teachers, especially new ones, who struggle with discipline, noise and nerves.','We ask God to give us calm authority and a heart for the children in front of us.','We swap classroom ideas, role-play hard moments and encourage each other on the worst days.','By week 12 each of us has a clear routine for the start and end of lessons, a simple set of class rules and one lesson watched and discussed with a colleague.','Routines for the start and end of lessons, simple class rules and one lesson discussed with a colleague.','Write the three moments in class that drain you most. Choose one routine for starting lessons and one for ending them.','Agree a few clear class rules and explain them calmly. Practise your opening lines aloud with someone in the tribe.','Ask a colleague to watch a lesson and give two comments. Share what you will keep, and what you will change.','Leaders never discuss pupils by name or share school records. Concerns about a child''s safety go to the school and the care ladder.',array['rising','builders']::text[],'weeknight-evening','online','Teaches with calm authority and remembers their early struggles. Encouraging and practical.',2,2,3,3,false),
('start-or-grow-a-school-tutoring-or-training','education','learning','Start or grow a school, tutoring or training venture',8,'Educators and entrepreneurs starting or growing a school, a tutoring service or a training programme.','We ask God to make our work a blessing to children and families, and to keep our motives clean.','We share what we learn about running a venture, visit each other''s work and refer learners honestly.','By week 12 each of us has a written plan for who we serve, what it costs and the income it needs, and has enrolled or contacted our first learners.','A written plan for learners, costs and income, and first learners enrolled or contacted.','Write who you will serve, what they need and what you will charge. Visit one working school or tutoring service and ask what they wish they had known.','Find out the registration and safety rules that apply. Write a simple budget for the first term.','Enrol or contact your first learners. Share what happened and what you will change next term.','Leaders do not give legal, tax or regulatory advice and do not endorse any venture to the church. Members must follow the rules for schools and child safety.',array['builders','stewards']::text[],'weeknight-evening','online','Has run or helped run a school or training venture and knows the rules and the real costs. Careful about children''s safety.',3,1,3,2,false),
('choose-a-course-or-career-path-with-clarity','education','learning','Choose a course or career path with clarity',9,'Students and school leavers who must choose a course, a school or a first career and feel pressure from many sides.','We ask God what He has placed in us, and we are willing to hear Him through counsel and through our own gifts.','We listen without pushing our own plans, share honest stories of the paths we took and respect each person''s choice.','By week 12 each of us has listed our strengths and interests, spoken with three people in fields we are considering and written our decision with reasons.','Strengths and interests listed, three conversations held, and a written decision with reasons.','List what you enjoy, what you are good at and what matters to you. Ask three people who know you well what strengths they see.','Speak with three people in fields you are considering and ask what a normal week looks like. Find out what each course really requires.','Write your decision and your reasons, and share them with your family and the tribe. Plan your next step and date.','Leaders do not tell anyone what to study or pressure them toward a field. They ask questions and the member decides, with their family.',array['rising']::text[],'weeknight-evening','online','Chose a path with care and can talk about their detours without pressure. Patient with young people and their families.',2,3,3,1,false),
('prepare-for-my-licensing-or-exit-exams','medical-healthcare','career-calling','Prepare for my licensing or exit exams',3,'Doctors, nurses, pharmacists and other health workers preparing for a licensing or exit exam.','We prepare with diligence, rest on the day set apart and trust God with the result.','We quiz each other, share notes and pray for each other before the exams.','By week 12 each of us has covered the syllabus on a plan, done timed practice papers and booked a date for the exam.','The syllabus covered on a plan, timed practice papers done and the exam date booked.','Get the syllabus and the exam date. Divide the topics into twelve weeks and mark the ones you find hardest.','Protect a study block each week, even on heavy shifts. Quiz a partner in the tribe on the hardest topics.','Do timed practice papers and learn from every error. Plan the final week with rest and prayer.','Leaders give no medical advice and never discuss patients. Names and cases stay out of the tribe. They never share or look for leaked questions.',array['rising','builders']::text[],'weeknight-evening','online','Has passed licensing or exit exams while working and can explain how they found time to study. Calm and organised.',3,1,3,2,false),
('care-with-compassion-at-the-bedside','medical-healthcare','career-calling','Care with compassion at the bedside',4,'Nurses, doctors and carers who want to stay kind and present while the work is relentless.','We ask God to see each patient through His eyes, and to keep our hearts soft when we are tired.','We share the hardest moments without naming patients, pray for each other and remind each other of why we began.','By week 12 each of us has a short habit that brings us back to the person in the bed, a way of resetting after hard cases and one kind act each shift.','A habit that brings us back to the person, a way of resetting after hard cases and one kind act each shift.','Write what first drew you to this work and what has worn it down. Choose a short habit to pause before each patient, such as one breath and one prayer.','Each shift, do one small act of kindness that costs you nothing. Share one story with the tribe, with no names or details.','Find a way to reset after a hard case, such as a walk, a call or a prayer. Tell the tribe what has helped.','Leaders give no medical advice and never discuss patients. Names and cases stay out of the tribe. Anything that harms a patient or a colleague goes to the right authority and the care ladder.',array['rising','builders','stewards']::text[],'weeknight-evening','online','Has cared at the bedside for years and kept a soft heart. Honest about compassion fatigue and discreet.',1,3,2,2,true),
('serve-underserved-communities-through-outreach','medical-healthcare','career-calling','Serve underserved communities through outreach',5,'Health workers who want to give their skills to communities that cannot easily afford care.','We see outreach as love of neighbour, and we ask God to keep our hearts humble and our work honest.','We plan together, share transport and supplies and learn from each other''s experience of the field.','By week 12 each of us has joined or planned a community outreach with a clear purpose, a team and a date, and has served at least once.','A community outreach planned or joined, with a clear purpose, a team and a date, and at least one service given.','Choose a community and a need. Find out who already serves there and how you can join or partner with them.','Plan the outreach with a team: purpose, date, supplies, transport and safety. Get permission from the right people.','Serve at least once and write what you learned. Share with the tribe what you will do next.','Leaders do not treat patients through the tribe, give medical advice or promise treatment. All outreach follows the rules for health workers and child safety.',array['rising','builders','stewards']::text[],'saturday-morning','in_person','Has served on outreach and understands the preparation it needs. Humble, organised and safety-minded.',3,2,1,3,false),
('build-a-private-practice-or-health-business','medical-healthcare','career-calling','Build a private practice or health business',6,'Health professionals who want to start or grow a clinic, a pharmacy, a laboratory or another health business.','We ask God to make our work a blessing to patients and to keep us honest in every bill and every record.','We share what we learn about licences, staff and equipment, and we refer to one another honestly.','By week 12 each of us has a written plan covering licence, location, costs and first patients, and has spoken to at least three people who run similar businesses.','A written plan covering licence, location, costs and first patients, and three conversations with people who run similar businesses.','Write what service you want to offer, who for and where. Find out what licences and approvals you need.','Speak to three people who run similar services and ask about costs, staff and surprises. Build a simple budget for the first six months.','Take the next legal or practical step, such as a licence application or a location visit. Share your plan with the tribe.','Leaders do not give legal, regulatory, tax or medical advice. All practice must follow the rules for health professionals in Nigeria.',array['builders','stewards']::text[],'weeknight-evening','online','Has built or run a health business and understands both care and cost. Honest about what went wrong.',3,1,3,2,false),
('lead-a-ward-or-team-well','medical-healthcare','career-calling','Lead a ward or team well',7,'Nurses, doctors and managers who lead a ward, unit or team and want to do it with fairness and care.','We lead as servants, ask God for wisdom in hard decisions and pray for the people we supervise.','We share real leadership problems without naming staff or patients, and learn from each other''s mistakes.','By week 12 each of us has a weekly check-in with our team, a fair way of sharing hard shifts and one difficult conversation held with care.','A weekly team check-in, a fair way of sharing hard shifts and one difficult conversation held with care.','Write what your team needs from you most and where you fall short. Ask two team members for honest comments.','Start a short weekly check-in with your team and create a fair rota for hard shifts. Share what you learn with the tribe.','Hold the one difficult conversation you have been putting off, with care. Report how it went and what you will do next.','Leaders give no medical advice and never discuss patients. Names and cases stay out of the tribe. They never discuss individual staff by name.',array['builders','stewards']::text[],'weeknight-evening','online','Leads a clinical team and values fairness and kindness over control. Calm under pressure.',3,3,2,2,false),
('plan-a-move-to-practise-abroad-or-a-return-home','medical-healthcare','career-calling','Plan a move to practise abroad, or a return home',8,'Health workers thinking of practising in another country, or returning home after practising abroad.','We ask God where He wants us to serve, and we move only with open hands and a thankful heart.','We share honest stories of leaving and returning, count the cost together and pray for those we leave behind.','By week 12 each of us has a written plan covering exams, registration, money and family, and has spoken to two people who have made the same move.','A written plan covering exams, registration, money and family, and two conversations with people who made the same move.','Write why you are considering the move and what you would gain and lose. Share it with your family and the tribe.','List what the move requires: exams, registration, money, papers and family plans. Put a date next to each item.','Speak to two people who made the same move and ask what they would do differently. Write your decision and next step.','Leaders do not give immigration, licensing or financial advice. They share only their own experience and point to official sources.',array['rising','builders','stewards']::text[],'weeknight-evening','online','Has practised abroad or returned home and can speak about the real costs of both. Honest and balanced.',3,2,2,2,false),
('mentor-younger-colleagues-and-students','medical-healthcare','career-calling','Mentor younger colleagues and students',9,'Experienced health workers who want to guide younger colleagues and students with care.','We thank God for those who taught us and ask Him to make us patient, honest teachers.','We share what works in teaching, encourage each other when mentoring is hard and never speak badly of a student.','By week 12 each of us has met one younger colleague or student every two weeks, taught one practical skill and listened to one of their struggles.','Meetings with a younger colleague or student every two weeks, one practical skill taught and one struggle heard.','Choose a younger colleague or student to mentor and agree how often you will meet. Ask what they most need to learn.','Teach one practical skill and show them how you handle a hard moment. Listen to one struggle without fixing it.','Ask them what has helped and what has not. Share what you have learned about mentoring with the tribe.','Leaders give no medical advice and never discuss patients. Names and cases stay out of the tribe. They never discuss students or colleagues by name outside the pair.',array['builders','stewards','sages']::text[],'weeknight-evening','online','Has taught and mentored in clinical settings and does so with kindness. Patient and a good listener.',1,3,3,2,false),
('build-a-consistent-creative-practice','creative-economy','enterprise','Build a consistent creative practice',3,'Makers who create in bursts and want a steady rhythm, however small.','We make as an act of thanks to the Creator, and we ask Him to make our hands steady and our hearts free.','We keep each other to the hours we set, share work in progress and never mock rough drafts.','By week 12 each of us has made something on most days we planned, has a fixed creative time and has shown unfinished work to the tribe.','A fixed creative time kept, work made on most planned days and unfinished work shown.','Choose a daily or weekly creative time you can keep on a bad day. Set a small target, such as ten minutes or one page.','Keep the time for a month and mark each day on a calendar. Show a piece of work in progress to the tribe each week.','Review what helped and what blocked you. Set the practice for the next season.','Leaders do not judge anyone''s faith by the style or subject of their work. Content must be fit for a church family.',array['rising','builders','stewards']::text[],'weeknight-evening','online','Keeps a regular creative practice and treats it as work. Gentle with those who struggle to start.',3,2,1,3,false),
('grow-an-audience-that-cares','creative-economy','enterprise','Grow an audience that cares',4,'Makers who share their work online or in person and want a small, real audience.','We share our work to bless people, and we ask God to guard us from chasing numbers.','We encourage each other''s work in public, give honest feedback in private and refuse to buy followers.','By week 12 each of us has shared our work on a regular schedule, replied to everyone who responded and built a list of at least fifty people who want to hear from us.','Work shared on a regular schedule, every reply answered and a list of fifty interested people.','Write who your work is for and what you want them to feel. Choose one place where those people already are.','Share your work on a regular schedule and reply to every person who responds. Ask three people what they would like more of.','Start a simple list of people who want to hear from you. Keep what worked and drop what did not.','Leaders do not promise followers or income, and do not endorse buying likes or followers. They share only honest ideas.',array['rising','builders']::text[],'weeknight-evening','online','Has built a real audience slowly and cares for the people in it more than the numbers.',2,2,3,3,false),
('win-my-first-paid-commissions','creative-economy','enterprise','Win my first paid commissions',5,'Makers whose work people admire but have not yet paid for.','We ask God for the right first clients and for humility in the work and in the asking.','We share leads, review each other''s offers and encourage each other to ask for payment.','By week 12 each of us has a portfolio of three pieces, a clear price for a commission and at least one paid commission agreed or finished.','A portfolio of three pieces, a clear commission price and one paid commission agreed or finished.','Choose your best three pieces and show them to five people. Write who might commission this work and what they would pay for.','Write a simple commission offer with a price, a timeline and what the client receives. Share it with ten possible clients.','Agree your first commission in writing and deliver it on time. Ask your client for a short testimonial.','Leaders do not give legal or financial advice. They point to a qualified professional.',array['rising','builders']::text[],'weeknight-evening','online','Gets paid for commissions and can explain how they got the first ones. Honest and practical.',3,1,2,3,false),
('build-a-creative-team-and-collaborate','creative-economy','enterprise','Build a creative team and collaborate',6,'Makers who work alone and want to make something bigger with others.','We make with others because God made us for community, and we give credit where it is due.','We listen to each other''s ideas, share the work and the credit fairly and work through conflict kindly.','By week 12 each of us has found at least two collaborators, agreed roles and credit in writing and made one shared piece together.','Two collaborators found, roles and credit agreed in writing, and one shared piece made.','List the skills you lack and the people whose work you admire. Ask two of them to coffee and share an idea.','Agree roles, deadlines and credit in writing before you begin. Start with a small shared piece.','Finish and share the piece together. Tell the tribe what worked, what was hard and who you would work with again.','Leaders do not give legal or financial advice. They point to a qualified professional.',array['rising','builders','stewards']::text[],'weeknight-evening','in_person','Collaborates well and shares credit generously. Calm in creative disagreement.',2,3,2,3,false),
('protect-my-work-rights-contracts-and-fair-pay','creative-economy','enterprise','Protect my work: rights, contracts and fair pay',7,'Makers who have been underpaid, copied or asked to work for free.','We ask God to help us be fair to others and to ask fairness for ourselves, without bitterness.','We share templates, read each other''s agreements and say no together to unfair terms.','By week 12 each of us understands who owns our work, has a written agreement for each job and has said no to one unfair request.','Ownership of our work understood, a written agreement for each job and one unfair request refused.','List jobs where you were underpaid, copied or unclear about rights. Write what you wish had been agreed in advance.','Learn the basics of who owns creative work in your field and draft a simple agreement. Ask a lawyer or a creators'' group to check it.','Use the agreement with your next job and say no to one unfair request. Share what you learned.','Leaders do not write contracts or give legal advice. They share simple templates and point to a lawyer or creator''s association.',array['builders','stewards']::text[],'weeknight-evening','online','Has been burned by a bad agreement and now works with clear terms. Calm and practical.',3,1,3,2,false),
('use-my-gift-to-serve-the-church-and-the-city','creative-economy','enterprise','Use my gift to serve the church and the city',8,'Makers who want to offer their gifts to the church and to others.','We offer our gifts to God as worship and ask Him to keep us from pride and from comparison.','We serve alongside each other, support each other''s projects and celebrate service done in quiet.','By week 12 each of us has agreed one specific way to serve with our gift, delivered it at least twice and invited another maker to join.','One specific way of serving agreed, delivered at least twice, and another maker invited.','Write what you can offer and who could use it, in the church or in your area. Speak to a leader or a team about where you could help.','Agree one specific piece of service with a date. Deliver it and ask for honest feedback.','Serve again and invite another maker to join you. Share what you learned about serving with a gift.','Leaders do not decide church roles and do not promise any project a place in a service. They help members offer their gifts to the right team.',array['rising','builders','stewards','sages']::text[],'sunday-afternoon','in_person','Serves with their creative gift and encourages others to do the same. Humble and reliable.',2,3,1,3,false),
('work-through-creative-block-and-comparison','creative-economy','enterprise','Work through creative block and comparison',9,'Makers who feel stuck, flat or smaller than other people''s work.','We tell God honestly how we feel about our work and trust that He sees it and us.','We encourage without flattery, share our stuck moments and remind each other that comparison is not the standard.','By week 12 each of us has found three things that get us moving again, stopped following one account that fuels comparison and finished one small piece.','Three things that get us moving, one comparison source removed and one small piece finished.','Write what you feel when you sit down to make something. Name who you compare yourself to and what exactly you envy.','Try three small things that have helped other makers, such as a short daily exercise, a change of place or a small project. Keep the ones that work.','Finish one small piece, however rough, and show it to the tribe. Stop following one account that makes you feel smaller.','Leaders do not give mental health advice. If a member seems very low, they encourage them to speak to a professional and use the care ladder.',array['rising','builders','stewards']::text[],'weeknight-evening','online','Has been stuck and come through it. Gentle, honest about doubt and not given to quick fixes.',1,3,1,3,false)
    ) as v (slug, community_slug, family_slug, title, sort,
            who_for, loving_god, loving_others, loving_life, week12_outcome, arc_1, arc_2, arc_3, guardrail, track_slugs,
            rhythm_slot, rhythm_mode, who_leads_well, ds, dc, dt, dd, sensitive)
    join public.communities c on c.slug = v.community_slug
    join public.goal_families f on f.slug = v.family_slug
  on conflict (slug) do nothing;

  select count(*) into v_n from public.tribe_card_templates;
  if v_n <> 100 then
    raise exception 'Expected 100 card templates after the seed, found %', v_n;
  end if;
  -- The 77 are new goals: none is linked to a goal yet. A goal is made only when its card is signed off.
  select count(*) into v_n from public.tribe_card_templates where season_goal_id is null;
  if v_n <> 77 then
    raise exception 'Expected 77 cards without a goal, found %', v_n;
  end if;
  -- None may collide with a goal that is already there under another community or another title.
  select count(*) into v_n
    from public.tribe_card_templates t
    join public.season_goals g on g.slug = t.slug or (g.community_id = t.community_id and lower(g.title) = lower(t.title))
   where t.season_goal_id is null;
  if v_n <> 0 then
    raise exception '% of the 77 new cards clash with a goal that already exists', v_n;
  end if;
end
$seed$;
